-- Data-subject export and anonymisation workflow (FR-AUD-002, 003), ADR 014.

-- ============ Part 1: tables (generated by prisma migrate diff) ============
-- AlterTable
ALTER TABLE "users" ADD COLUMN     "anonymised_at" TIMESTAMPTZ;

-- CreateTable
CREATE TABLE "privacy_requests" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "org_id" UUID NOT NULL,
    "subject_user_id" UUID NOT NULL,
    "type" VARCHAR(12) NOT NULL,
    "status" VARCHAR(12) NOT NULL DEFAULT 'PENDING',
    "requested_by" UUID NOT NULL,
    "reason" TEXT NOT NULL DEFAULT '',
    "blockers" JSONB NOT NULL DEFAULT '[]',
    "result" JSONB,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "completed_at" TIMESTAMPTZ,

    CONSTRAINT "privacy_requests_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "privacy_requests_org_id_subject_user_id_idx" ON "privacy_requests"("org_id", "subject_user_id");

-- AddForeignKey
ALTER TABLE "privacy_requests" ADD CONSTRAINT "privacy_requests_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "privacy_requests" ADD CONSTRAINT "privacy_requests_subject_user_id_fkey" FOREIGN KEY ("subject_user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "privacy_requests" ADD CONSTRAINT "privacy_requests_requested_by_fkey" FOREIGN KEY ("requested_by") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;



-- ============ Part 2: rules, security (hand-written) ============

ALTER TABLE privacy_requests
  ADD CONSTRAINT privacy_requests_type_check CHECK (type IN ('EXPORT', 'ANONYMISE')),
  ADD CONSTRAINT privacy_requests_status_check CHECK (status IN ('PENDING', 'BLOCKED', 'COMPLETED', 'CANCELLED'));
-- One open anonymisation per person at a time.
CREATE UNIQUE INDEX privacy_requests_one_open_anonymisation ON privacy_requests (subject_user_id) WHERE type = 'ANONYMISE' AND status IN ('PENDING', 'BLOCKED');

ALTER TABLE privacy_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE privacy_requests FORCE ROW LEVEL SECURITY;
CREATE POLICY privacy_requests_org_policy ON privacy_requests FOR ALL
  USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid)
  WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
-- The workflow record is kept: no deletes by the application.
GRANT SELECT, INSERT, UPDATE ON privacy_requests TO hrvo_app;

-- FR-AUD-003: anonymisation redacts the free text of locked time entries. Only inside a
-- transaction that sets app.anonymising, and only when nothing but note / manual_reason changes.
CREATE OR REPLACE FUNCTION fn_time_entries_lock_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  st TEXT;
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND current_setting('app.anonymising', true) = 'on'
     AND NEW.timesheet_id = OLD.timesheet_id AND NEW.user_id = OLD.user_id AND NEW.minutes = OLD.minutes
     AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at AND NEW.ended_at IS NOT DISTINCT FROM OLD.ended_at
     AND NEW.project_id IS NOT DISTINCT FROM OLD.project_id AND NEW.task_id IS NOT DISTINCT FROM OLD.task_id
     AND NEW.billable = OLD.billable AND NEW.work_date = OLD.work_date AND NEW.source = OLD.source THEN
    RETURN NEW;
  END IF;
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT status INTO st FROM timesheets WHERE id = OLD.timesheet_id;
    IF st IS NOT NULL AND st NOT IN ('DRAFT', 'REJECTED') THEN
      RAISE EXCEPTION 'timesheet is %, its time entries are locked', st USING ERRCODE = 'P0001', HINT = 'TIMESHEET_LOCKED';
    END IF;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT status INTO st FROM timesheets WHERE id = NEW.timesheet_id;
    IF st IS NOT NULL AND st NOT IN ('DRAFT', 'REJECTED') THEN
      RAISE EXCEPTION 'timesheet is %, its time entries are locked', st USING ERRCODE = 'P0001', HINT = 'TIMESHEET_LOCKED';
    END IF;
    RETURN NEW;
  END IF;
  RETURN OLD;
END
$$;
